head.script:
// 샘플에 직접 유효성 설정
scwin.tData = {
    "description" : "[multiselect > M > deleteSelectedItems]<br/>Multiselect 컴포넌트의 선택되어 있는 모든 아이템을 제거합니다.",
    "validation" : [
        "선택되어 있는 모든 아이템을 일괄 제거합니다.",
        "refresh(선택) 파라미터로 아이템이 BindItemSet 으로 정의된 경우 DataCollection 에 반영 여부를 설정합니다.",
        "refresh(선택) 파라미터로 true 설정 시 아이템이 정의된 DataCollection 에서 해당 아이템들을 제거합니다.",
        "refresh(선택) 파라미터로 false 설정 시 아이템이 정의된 DataCollection 에서 해당 아이템들을 제거하지 않습니다.",
        "refresh(선택) 파라미터를 생략하면 dataListAutoRefresh 속성값이 적용됩니다.",
        "선택된 아이템이 하나도 없으면 아무 동작도 수행하지 않습니다.",       
        "선택된 모든 아이템을 일괄 제거하고 반환값이 없습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성 (BindItemSet: gdl_multiselect 와 바인딩, dataListAutoRefresh 속성 적용)
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // gdl_multiselect 재생성 (idempotent: 기존 dataList 제거 후 재생성)
    $c.gcm.createDataListMultiSelect();

    let properties = {
        dataListAutoRefresh : con_dataListAutoRefresh.getText()
    }

    let cList = $c.gcm.createCList(properties);

    $c.gcm.createBasicMultiSelect(cList);
}



// deleteSelectedItems 메소드 호출 (refresh 파라미터 생략/true/false)
scwin.btn_deleteSelectedItems_onclick = function (e) {
    let refresh = par_refresh.getText();
    let rtn;

    if (refresh === '') {
        rtn = target1.deleteSelectedItems();
    } else {
        rtn = target1.deleteSelectedItems(refresh === 'true');
    }

    wf_body_bottom.getObj("scwin").setReturnValue("return : " + rtn);
};



// 전체 아이템 갯수 확인
scwin.btn_getItemCount_onclick = function (e) {
    let cnt = target1.getItemCount();
    wf_body_bottom.getObj("scwin").setReturnValue("getItemCount : " + cnt);
};



// 바인딩된 DataList 의 현재 값 확인
scwin.btn_getDataList_onclick = function (e) {
    let rsData = gdl_multiselect.getAllJSON();

    wf_body_bottom.getObj("scwin").setReturnValue("DataList Row 수 : " + rsData.length);
    for (let i = 0; i < rsData.length; i++) {
        wf_body_bottom.getObj("scwin").setReturnValue("[" + i + "] value=" + rsData[i].value + ", label=" + rsData[i].label);
    }
};
